import React, { useEffect } from 'react';
import { graphql, Link, PageProps, HeadFC } from 'gatsby';
import Layout from '../components/Layout';
import Sidebar from '../components/Sidebar';
import SeriesPrevNext from '../components/SeriesPrevNext';
import SeriesContext from '../components/SeriesContext';
import OptimizedImage from '../components/OptimizedImage';
import SEO from '../components/SEO';
import Comments from '../components/Comments';
import ImageSpinner from '../components/ImageSpinner';
import ShareButtons from '../components/ShareButtons';
import ArticleMeta from '../components/ArticleMeta';
import DraftBanner from '../components/DraftBanner';
import { tagMatches, getTagPath } from '../utils/tagUtils';
import { postProcessImages, postProcessTables, postProcessAffiliateLinks } from '../utils/postProcessImages';
import { slugifySeriesName } from '../utils/articlePath';
import type { SeriesMetadata, SeriesArticle } from '../types';
import type { SpinnerImage, NamedSpinner, ShareCounts } from '../types/article';

interface SeriesArticleData {
  markdownRemark: {
    id: string;
    html: string;
    frontmatter: {
      slug: string;
      title: string;
      excerpt: string;
      featuredImage: string;
      tags: string[] | null;
      author: string;
      publishedAt: string;
      updatedAt: string;
      imageSpinner?: SpinnerImage[];
      imageSpinners?: NamedSpinner[];
      series: {
        name: string;
        order?: number;
        description?: string;
        featuredImage?: string;
        references?: Array<{
          url: string;
          title?: string;
        }>;
        attachments?: Array<{
          filename: string;
          title?: string;
        }>;
      };
      draft?: boolean;
    };
  };
  authorsJson: {
    name: string;
    slug: string;
    bio: string;
    avatar: string;
  };
  site: {
    siteMetadata: {
      title: string;
      description: string;
      siteUrl: string;
    };
  };
  seriesArticles: {
    nodes: Array<{
      frontmatter: {
        slug: string;
        title: string;
        publishedAt: string;
        featuredImage: string;
        series?: {
          order?: number;
        };
      };
    }>;
  };
}

interface SeriesArticlePageContext {
  viewCount: number;
  commentCount: number;
  readingTime: number;
  shareCounts: ShareCounts;
  isBrewing?: boolean;
  isReview?: boolean;
}

const SeriesArticleTemplate: React.FC<PageProps<SeriesArticleData, SeriesArticlePageContext>> = ({ data, pageContext }) => {
  const article = data.markdownRemark.frontmatter;
  const articleHtml = postProcessAffiliateLinks(postProcessTables(postProcessImages(data.markdownRemark.html)));
  const author = data.authorsJson;
  const viewCount = pageContext.viewCount || 0;
  const commentCount = pageContext.commentCount || 0;
  const readingTime = pageContext.readingTime || 0;
  const shareCounts = pageContext.shareCounts || { facebook: 0, twitter: 0, linkedin: 0, copy: 0 };
  
  // Announce context to SupportBar component
  useEffect(() => {
    let context: 'brewing' | 'reviews' | 'tech' = 'tech';
    const isBrewing = pageContext.isBrewing ?? false;
    if (isBrewing || (article.tags && article.tags.some(t => t.toLowerCase().includes('brewing')))) {
      context = 'brewing';
    } else if (pageContext.isReview) {
      context = 'reviews';
    }
    
    const event = new CustomEvent('support-context', { detail: { context } });
    window.dispatchEvent(event);
  }, [pageContext.isBrewing, pageContext.isReview, article.tags]);
  
  // Get the first tag that's not "family" or "featured" for display
  const primaryTag = article.tags?.find(tag => !tagMatches(tag, 'family') && !tagMatches(tag, 'featured')) || article.tags?.[0];

  // Prepare series metadata
  const seriesMetadata: SeriesMetadata = {
    name: article.series.name,
    order: article.series.order,
    references: article.series.references,
    attachments: article.series.attachments,
  };

  // Prepare series articles for table of contents
  const seriesArticles: SeriesArticle[] = data.seriesArticles.nodes.map((node) => ({
    slug: node.frontmatter.slug,
    title: node.frontmatter.title,
    publishedAt: node.frontmatter.publishedAt,
    featuredImage: node.frontmatter.featuredImage,
    order: node.frontmatter.series?.order,
  }));

  // Sort articles by order and find prev/next based on position
  const sortedArticles = [...seriesArticles].sort((a, b) =>
    (a.order || 0) - (b.order || 0)
  );

  const shareUrl = `https://josephcrawford.com/series/${slugifySeriesName(article.series.name)}/`;
  const shareImage = sortedArticles[0]?.featuredImage || article.featuredImage;

  // Find current article index
  const currentIndex = sortedArticles.findIndex((a) => a.slug === article.slug);

  // Get prev/next based on position
  const prevArticleData = currentIndex > 0
    ? sortedArticles[currentIndex - 1]
    : null;

  const nextArticleData = currentIndex < sortedArticles.length - 1
    ? sortedArticles[currentIndex + 1]
    : null;

  const displayTitle = article.title;
  const displayFeaturedImage = article.featuredImage || shareImage;

  // Process content with inline spinners
  const renderContentWithSpinners = (): React.ReactNode[] => {
    const spinners = article.imageSpinners;
    if (!spinners || spinners.length === 0) {
      return [<div key="content" className="hm-article-content" dangerouslySetInnerHTML={{ __html: articleHtml }} />];
    }

    // Build a lookup from spinner id to spinner data
    const spinnerMap = new Map<string, { images: SpinnerImage[] | null }>();
    for (const spinner of spinners) {
      spinnerMap.set(spinner.id, spinner);
    }

    // Find all spinner markers in HTML order
    const markerRegex = /<!--\s*spinner:([\w-]+)\s*-->/g;
    const parts: React.ReactNode[] = [];
    let keyIndex = 0;
    let lastIndex = 0;
    let match: RegExpExecArray | null;

    while ((match = markerRegex.exec(articleHtml)) !== null) {
      const before = articleHtml.substring(lastIndex, match.index);
      const spinnerId = match[1];

      if (before.trim()) {
        parts.push(<div key={`part-${keyIndex++}`} className="hm-article-content" dangerouslySetInnerHTML={{ __html: before }} />);
      }

      const spinnerData = spinnerMap.get(spinnerId);
      if (spinnerData?.images && spinnerData.images.length > 0) {
        parts.push(<ImageSpinner key={`spinner-${spinnerId}`} images={spinnerData.images} />);
      }

      lastIndex = match.index + match[0].length;
    }

    // Append any remaining HTML after the last marker
    const remaining = articleHtml.substring(lastIndex);
    if (remaining.trim()) {
      parts.push(<div key={`part-${keyIndex++}`} className="hm-article-content" dangerouslySetInnerHTML={{ __html: remaining }} />);
    }

    return parts;
  };

  return (
    <Layout>
      {article.draft && <DraftBanner />}
      <div className="hm-container">
        <div className="hm-content-sidebar-wrap">
          <main className="hm-primary-content">
            {/* Series Navigation - Top */}
            {(prevArticleData || nextArticleData) && (
              <SeriesPrevNext
                prevSlug={prevArticleData?.slug}
                prevTitle={prevArticleData?.title}
                nextSlug={nextArticleData?.slug}
                nextTitle={nextArticleData?.title}
                seriesName={article.series.name}
                position="top"
              />
            )}

            <article className="hm-article">
              <header className="hm-article-header">
                {primaryTag && (
                  <Link
                    to={`${getTagPath(primaryTag)}/`}
                    className="hm-article-category"
                  >
                    {primaryTag}
                  </Link>
                )}

                <h1 className="hm-article-title">{displayTitle}</h1>

                <ArticleMeta
                  authorName={author.name}
                  publishedAt={article.publishedAt}
                  viewCount={viewCount}
                  commentCount={commentCount}
                  readingTime={readingTime}
                  byText="by"
                  variant="article"
                />

                <ShareButtons
                  title={article.series.name}
                  url={shareUrl}
                  variant="top"
                  shareCounts={shareCounts}
                />
              </header>

              {/* Series Context - Auto-generated */}
              <SeriesContext
                seriesName={article.series.name}
                currentOrder={article.series.order}
                totalArticles={seriesArticles.length}
              />

              {!(article.imageSpinner && article.imageSpinner.length > 0) && (
                <div className="hm-article-featured-image">
                  <OptimizedImage
                    src={displayFeaturedImage}
                    alt={article.title}
                    loading="eager"
                    sizes="(max-width: 768px) 100vw, 850px"
                  />
                </div>
              )}

              {article.imageSpinner && article.imageSpinner.length > 0 && (
                <ImageSpinner images={article.imageSpinner} />
              )}

              {renderContentWithSpinners()}

              <div className="hm-article-footer">
                <hr />

                {(article.tags?.length ?? 0) > 0 && (
                  <div className="hm-article-tags">
                    <span className="hm-article-tags-label">Tags:</span>
                    {article.tags?.map((tag) => (
                      <span key={tag} className="hm-article-tag">
                        {tag}
                      </span>
                    ))}
                  </div>
                )}

                {(article.tags?.length ?? 0) > 0 && <hr />}

                <ShareButtons
                  title={article.series.name}
                  url={shareUrl}
                  shareCounts={shareCounts}
                />

                <hr />

                <Comments slug={article.slug} title={article.title} />
              </div>
            </article>

            {/* Series Navigation - Bottom */}
            {(prevArticleData || nextArticleData) && (
              <SeriesPrevNext
                prevSlug={prevArticleData?.slug}
                prevTitle={prevArticleData?.title}
                nextSlug={nextArticleData?.slug}
                nextTitle={nextArticleData?.title}
                seriesName={article.series.name}
                position="bottom"
              />
            )}
          </main>

          {/* Sidebar - Only Series Widget */}
          <Sidebar
            currentSlug={article.slug}
            series={seriesMetadata}
            seriesArticles={seriesArticles}
          />
        </div>
      </div>
    </Layout>
  );
};

export const query = graphql`
  query SeriesArticleQuery(
    $slug: String!
    $author: String!
    $seriesName: String!
  ) {
    markdownRemark(frontmatter: { slug: { eq: $slug } }, fileAbsolutePath: { regex: "/content/(posts|reviews|brewing)/" }) {
      id
      html
      frontmatter {
        slug
        title
        excerpt
        featuredImage
        tags
        author
        publishedAt
        draft
        updatedAt
        imageSpinner {
          src
          alt
          caption
        }
        imageSpinners {
          id
          images {
            src
            alt
            caption
          }
        }
        series {
          name
          order
          description
          featuredImage
          references {
            url
            title
          }
          attachments {
            filename
            title
          }
        }
      }
    }
    authorsJson(slug: { eq: $author }) {
      name
      slug
      bio
      avatar
    }
    site {
      siteMetadata {
        title
        description
        siteUrl
      }
    }
    seriesArticles: allMarkdownRemark(
      filter: { frontmatter: { series: { name: { eq: $seriesName } } } }
      sort: [
        { frontmatter: { series: { order: ASC } } }
        { frontmatter: { publishedAt: ASC } }
      ]
    ) {
      nodes {
        frontmatter {
          slug
          title
          publishedAt
          featuredImage
          series {
            order
          }
        }
      }
    }
  }
`;

export const Head: HeadFC<SeriesArticleData> = ({ data }) => {
  const frontmatter = data.markdownRemark.frontmatter;
  const seriesName = frontmatter.series.name;
  const seriesDescription = frontmatter.series.description;
  const seriesImage = frontmatter.series.featuredImage;

  const sortedSeriesArticles = [...data.seriesArticles.nodes].sort((a, b) => {
    const orderA = a.frontmatter.series?.order ?? Infinity;
    const orderB = b.frontmatter.series?.order ?? Infinity;
    return orderA - orderB;
  });
  const firstArticle = sortedSeriesArticles[0]?.frontmatter;

  const displayTitle = seriesName;
  const displayDescription = seriesDescription || frontmatter.excerpt;
  const displayImage = frontmatter.featuredImage || seriesImage || firstArticle?.featuredImage;

  return (
    <SEO
      title={displayTitle}
      description={displayDescription}
      image={displayImage}
      article={true}
      pathname={`/series/${slugifySeriesName(seriesName)}/`}
      siteMetadata={data.site.siteMetadata}
    />
  );
};

export default SeriesArticleTemplate;
